class Solution {
public:
    int findSubstringInWraproundString(string p) {
        vector<int> maxLen(26, 0);
        int k = 0;

        for (int i = 0; i < p.size(); i++) {
            if (i > 0 && ((p[i] - p[i-1] + 26) % 26 == 1)) {
                k++;
            } else {
                k = 1;
            }
            int idx = p[i] - 'a';
            maxLen[idx] = max(maxLen[idx], k);
        }

        int result = 0;
        for (int len : maxLen) {
            result += len;
        }
        return result;
    }
};

