      if (wordSet.count(prefix))
        for (const string& word : wordBreak(prefix, wordSet, memo))
          ans.push_back(prefix + " " + word);
    }

    // Contains whole string, so don't add any space
    if (wordSet.count(s))
      ans.push_back(s);

    return memo[s] = ans;
  }
};

