class Solution {
public:
    vector<string> readBinaryWatch(int turnedOn) {
        int mh = (1<<4) - 1, mm = (1<<6) - 1;
        vector<string> ans;
        for(int ih=0; ih<=mh; ih++){
            for(int im=0; im<=mm; im++){
                if(__builtin_popcount(ih) + __builtin_popcount(im) != turnedOn)
                    continue;
                int hr = 0, mn = 0;
                for(int i=0; i<=5; i++){
                    if((ih>>i)&1)
                        hr += (1<<i);
                    if((im>>i)&1)
                        mn += (1<<i);
                } 
                if(hr>=12 || mn>=60)
                        continue;
                string tm = "00:00";
                tm[0] += hr/10, tm[1] += hr%10;
                tm[3] += mn/10, tm[4] += mn%10;
                if(tm[0]=='0')
                    tm.erase(tm.begin());
                ans.push_back(tm);

            }
        }
        return ans;
    }
};

