class Solution {
    vector<vector<int>> result;   
    queue<TreeNode *>que;
    void levelorder(TreeNode *p){
        if(p){
            que.push(p);
        }
        while(!que.empty()){
            vector<int>temp;
            int size=que.size();
            for(int i=0;i<size;i++){
                TreeNode *t=que.front();
                que.pop();
                temp.push_back(t->val);
                if(t->left){
                    que.push(t->left);
                }
                if(t->right){
                    que.push(t->right);
                }
            }
            result.push_back(temp);
        }
    }
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if(root==NULL){
            return {};
        }
        levelorder(root);
        return result;

    }
};

