class Solution {
public:
    vector<vector<int>> getSkyline(vector<vector<int>>& buildings) {
        vector<vector<int>> res;
        priority_queue<pair<int,int>> pq;
        int curr_h = 0, curr_x = INT_MIN;

        sort(buildings.begin(), buildings.end());

        for (int i = 0; i <= buildings.size(); ++i) {
            while (!pq.empty() && (i == buildings.size() || buildings[i][0] >= pq.top().second)) {
                while (!pq.empty() && pq.top().second <= curr_x) pq.pop();

                int end_x = INT_MIN;
                int end_h = pq.top().first;
                if (end_h < curr_h) {
                    pq.pop();
                } else if (end_h == curr_h) {
                    do {
                        end_x = max(end_x, pq.top().second);
                        pq.pop();
                    } while (!pq.empty() && pq.top().first == curr_h);

                    while (!pq.empty() && pq.top().second <= end_x) pq.pop();
                    curr_h = pq.empty() ? 0 : pq.top().first;
                    if (curr_x < end_x) {
                        curr_x = end_x;
                        res.push_back({curr_x, curr_h});
                    }
                } else {
                    ++end_x;
                }
            }
            if (i < buildings.size()) {
                const auto& b = buildings[i];
                pq.emplace(b[2], b[1]);
                if (curr_h < b[2] || curr_x == b[0]) {
                    if (curr_x < b[0])
                        res.push_back({b[0], b[2]});
                    else if (b[2] > curr_h) {
                        if (res.back()[0] == curr_x)
                            res.pop_back();
                        if (res.empty() || res.back()[1] != b[2])
                            res.push_back({b[0], b[2]});
                    }
                    curr_h = res.back()[1];
                }
                curr_x = b[0];
            }
        }
        return res;
    }
};

