int dist[4950] = {INT_MAX};
int saved[4950];

class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {
        for (int i = 0; i < n; i++) dist[i] = INT_MAX;
        dist[src] = 0;
        for (int i = 0; i <= k; i++) {
            memcpy(saved, dist, sizeof(int) * n);
            for (auto& v : flights) {
                auto from = v[0];
                auto to = v[1];
                auto price = v[2];
                if (dist[from] != INT_MAX && dist[from] + price < saved[to]) {
                    saved[to] = dist[from] + price;
                }
            }
            memcpy(dist, saved, sizeof(int) * n);
        }
        return dist[dst] == INT_MAX ? -1 : dist[dst];
    }
};

